INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (1, 'Malayan Tiger', 'Panthera tigris jacksoni', 1, 'Carnivore', '8-15 years in the wild; 16-26 years in captivity', 'Malayan Tiger. The Malayan Tiger is Malaysia''s national animal. It has orange fur with black stripes — and no two tigers have the same pattern! People cut down forests and hunt tigers. They need big forests to survive!', 5, '/all_assets/wildlife-0.webp', '/avatars/malayan-tiger.png', 1);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (3, 'Sun Bear', 'Helarctos malayanus', 1, 'Omnivore (fruits + insects)', '15-25 years in the wild; 20-33 years in captivity', 'The Sun Bear is the smallest bear, with a short black coat and a golden patch on its chest. It has a long tongue for reaching honey and insects, and it is an excellent tree climber.', 5, '/all_assets/wildlife-1.webp', '/avatars/sun-bear.png', 3);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (4, 'Bornean Orangutan', 'Pongo pygmaeus', 1, 'Omnivore (fruits + insects)', '30–50 years in the wild; 40-60 years in captivity', 'The Bornean Orangutan is a super-smart "person of the forest" that shares almost the same DNA as us! They are the biggest animals in the world that live mostly in trees, where they build cozy new nests out of branches every single night. Grown-up males have big, wide faces and a special throat pouch to make "long calls" that echo through the jungle. These clever apes are great at using tools—they even make umbrellas out of leaves to stay dry! By eating fruit and spreading seeds, they act like forest gardeners, helping new trees grow across the island of Borneo.', 5, '/all_assets/wildlife-2.webp', '/avatars/bornean-orangutan.png', 4);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (5, 'Larut Torrent Frog', 'Amolops larutensis', 2, 'Insectivore', 'Unknown', 'The Larut Torrent Frog is a small frog that lives beside fast-flowing streams in forested mountains. It has strong legs and sticky toes that help it grip slippery rocks, and it is mostly active at night when it hunts for insects.', 1, '/all_assets/wildlife-3.webp', '/avatars/larut-torrent-frog.png', 5);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (6, 'Oriental Pied Hornbill', 'Anthracoceros albirostris', 3, 'Omnivore (fruits + small animals)', '25-30 years in the wild; up to 50 years in captivity', 'The Oriental Pied Hornbill is a black-and-white bird with a large curved beak topped by a casque. It lives in forests and feeds on fruits and small animals, and the female seals herself inside a tree hole to safely raise her chicks.', 1, '/all_assets/wildlife-4.webp', '/avatars/oriental-pied-hornbill.png', 6);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (7, 'Great Argus', 'Argusianus argus', 3, 'Omnivore (fruits + invertebrates)', '1 year in the wild; up to 20 years in captivity', 'The Great Argus is a large forest bird known for its long tail and amazing eye-like patterns on its wings. Males perform a special dance, spreading their wings wide to impress females during courtship.', 3, '/all_assets/wildlife-5.webp', '/avatars/great-argus.png', 7);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (8, 'Rhinoceros Hornbill', 'Buceros rhinoceros', 3, 'Omnivore (mainly fruit but also animals)', '10-40 years in the wild; 15-60 years in captivity', 'The Rhinoceros Hornbill is a large, colorful bird with a bright orange and yellow horn-like casque on its beak. It plays an important role in forests by spreading seeds after eating fruits.', 3, '/all_assets/wildlife-6.webp', '/avatars/rhinoceros-hornbill.png', 8);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (9, 'Paradise Flying Snake', 'Chrysopelea paradisi', 4, 'Carnivore (feeds on small vertebrates)', '4-12 years in the wild; 8-20 years in captivity', 'The Paradise Flying Snake is a slender green snake that can glide through the air from tree to tree. It flattens its body to catch the air and usually feeds on lizards and small animals.', 1, '/all_assets/wildlife-7.webp', '/avatars/paradise-flying-snake.png', 9);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (10, 'Saltwater Crocodile', 'Crocodylus porosus', 4, 'Carnivore', '70-100 years in the wild; 100-120 years in captivity', 'The Saltwater Crocodile is the largest living reptile and can be found in rivers, mangroves, and coastal waters. It is a powerful predator with strong jaws and can stay very still before attacking its prey.', 1, '/all_assets/wildlife-8.webp', '/avatars/saltwater-crocodile.png', 10);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (11, 'Little Mapwing', 'Cyrestis themire', 5, 'Herbivore (feeds on plant nectar)', 'Unknown', 'The Little Mapwing is a butterfly with delicate wings that look like a map pattern. It is often found in sunny forest areas, feeding on nectar and resting with its wings open.', 1, '/all_assets/wildlife-9.webp', '/avatars/little-mapwing.png', 11);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (12, 'Monarch', 'Danaus plexippus', 5, 'Herbivore (nectar)', '2-6 weeks (adult lifespan only)', 'The Monarch is a bright orange butterfly famous for its long-distance migration across countries. It feeds on nectar and lays its eggs on milkweed plants, which help protect its caterpillars.', 1, '/all_assets/wildlife-10.webp', '/avatars/monarch.png', 12);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (13, 'Leatherback Sea Turtle', 'Dermochelys coriacea', 4, 'Carnivore (feeds on jellyfish)', '30-50 years in the wild; 7-180 years in captivity', 'The Leatherback Sea Turtle is the largest sea turtle and has a soft, rubbery shell instead of a hard one. It travels across oceans and mainly eats jellyfish, helping keep marine ecosystems balanced.', 3, '/all_assets/wildlife-11.webp', '/avatars/leatherback-sea-turtle.png', 13);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (14, 'Asian Common Toad', 'Duttaphrynus melanostictus', 2, 'Insectivore', '4 years in the wild; up to 10 years in captivity', 'The Asian Common Toad is a hardy toad with rough, bumpy skin. It is often found near human homes and gardens, where it helps by eating insects like ants and beetles.', 1, '/all_assets/wildlife-12.webp', '/avatars/asian-common-toad.png', 14);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (15, 'Bornean Pygmy Elephant', 'Elephas maximus borneensis', 1, 'Herbivore', '50-70 years in the wild; 35-60 years in captivity', 'The Bornean Pygmy Elephant is the smallest elephant and has a round face, large ears, and a gentle nature. It lives in rainforest areas and spends most of its time eating plants and moving in small groups.', 4, '/all_assets/wildlife-13.webp', '/avatars/bornean-pygmy-elephant.png', 15);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (16, 'Black-crowned Pitta', 'Erythropitta ussheri', 3, 'Insectivore', '5-8 years in the wild', 'The Black-crowned Pitta is a brightly colored bird with a black head and vivid body feathers. It lives on the forest floor and uses its strong beak to hunt insects and small creatures.', 1, '/all_assets/wildlife-14.webp', '/avatars/black-crowned-pitta.png', 16);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (17, 'Common Grass Yellow', 'Eurema hecabe', 5, 'Herbivore (nectar)', '18 days (adult lifespan only)', 'The Common Grass Yellow is a small yellow butterfly commonly seen in open fields and gardens. It flies quickly and feeds on nectar from flowers during the day.', 1, '/all_assets/wildlife-15.webp', '/avatars/common-grass-yellow.png', 17);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (18, 'Kuhl''s Flying Gecko', 'Gekko kuhli', 4, 'Insectivore', '5-8 years in the wild, up to 10 years in captivity', 'Kuhl''s Flying Gecko is a tree-dwelling lizard that can glide using flaps of skin along its body. Its excellent camouflage helps it blend in with bark and avoid predators.', 1, '/all_assets/wildlife-16.webp', '/avatars/kuhl-s-flying-gecko.png', 18);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (20, 'Kissing Gourami', 'Helostoma temminckii', 6, 'Omnivore (algae + small organisms)', '5-15 years in the wild; 7-20 years in captivity', 'The Kissing Gourami is a freshwater fish known for its ''kissing'' behavior, where it presses its lips against others. It lives in slow-moving waters and feeds on algae and small plants.', 1, '/all_assets/wildlife-17.webp', '/avatars/kissing-gourami.png', 20);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (21, 'Spiny Terrapin', 'Heosemys spinosa', 4, 'Omnivore (plants + invertebrates)', '15-30 years in the wild; 20-40 years in captivity', 'The Spiny Terrapin is a freshwater turtle that has sharp spikes on its shell when young. It lives in rivers and forests and eats both plants and small animals.', 4, '/all_assets/wildlife-18.webp', '/avatars/spiny-terrapin.png', 21);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (22, 'Tiger Tail Seahorse', 'Hippocampus comes', 6, 'Carnivore (small crustaceans)', '1-5 years in the wild; 0-1.5 years in captivity', 'The Tiger Tail Seahorse is a small marine animal with striped patterns and a curled tail. It uses its tail to hold onto corals or plants while it waits to catch tiny drifting food.', 3, '/all_assets/wildlife-19.webp', '/avatars/tiger-tail-seahorse.png', 22);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (23, 'Asian Painted Frog', 'Kaloula pulchra', 2, 'Insectivore', '6-10 years in the wild and captivity', 'The Asian Painted Frog is a round-bodied frog with smooth, colorful skin. It spends much of its time underground and comes out during rainy weather to feed on insects.', 1, '/all_assets/wildlife-20.webp', '/avatars/asian-painted-frog.png', 23);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (24, 'Sunda Pangolin', 'Manis javanica', 1, 'Insectivore', 'Up to 7 years', 'The Sunda Pangolin is a shy, nocturnal animal covered in hard scales. It curls into a ball for protection and uses its long tongue to eat ants and termites.', 5, '/all_assets/wildlife-21.webp', '/avatars/sunda-pangolin.png', 24);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (25, 'Long-nosed Horned Frog', 'Megophrys nasuta', 2, 'Carnivore', '5-12 years in captivity', 'The Long-nosed Horned Frog has a pointed ''horn'' on its nose and looks like a dead leaf. This camouflage helps it hide while waiting to ambush insects and small prey.', 1, '/all_assets/wildlife-22.webp', '/avatars/long-nosed-horned-frog.png', 25);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (26, 'Proboscis Monkey', 'Nasalis larvatus', 1, 'Herbivore (leaves and fruits)', '10-13 years in the wild; 15-23 years in captivity', 'The Proboscis Monkey is famous for its large nose and round belly. It lives near rivers and mangroves, eats leaves and fruits, and is a strong swimmer.', 4, '/all_assets/wildlife-23.webp', '/avatars/proboscis-monkey.png', 26);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (27, 'Slender Skimmer', 'Orthetrum sabina', 5, 'Carnivore', '5-8 weeks (adult lifespan)', 'The Slender Skimmer is a common dragonfly found near ponds and rivers. It is a fast flyer and helps control mosquito populations by feeding on small insects.', 1, '/all_assets/wildlife-24.webp', '/avatars/slender-skimmer.png', 27);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (29, 'Guppy', 'Poecilia reticulata', 6, 'Omnivore', '0.5-3 years in the wild; 1-4 years in captivity', 'The Guppy is a small, colorful freshwater fish popular in aquariums. It is easy to care for, reproduces quickly, and feeds on tiny food particles and algae.', 1, '/all_assets/wildlife-25.webp', '/avatars/guppy.png', 29);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (30, 'Wallace''s Flying Frog', 'Rhacophorus nigropalmatus', 2, 'Insectivore', 'Up to 12 years', 'Wallace''s Flying Frog is a bright green frog with large webbed feet that help it glide between trees. It lives high in the forest canopy and rarely comes to the ground.', 1, '/all_assets/wildlife-26.webp', '/avatars/wallace-s-flying-frog.png', 30);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (31, 'Whale Shark', 'Rhincodon typus', 6, 'Carnivore (plankton)', '60-130 years in the wild; 0.25-19 years in captivity', 'The Whale Shark is the largest fish in the ocean, but it is gentle and harmless to humans. It swims slowly and feeds by filtering tiny plankton from the water.', 4, '/all_assets/wildlife-27.webp', '/avatars/whale-shark.png', 31);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (32, 'Crested Partridge', 'Rollulus rouloul', 3, 'Omnivore (seeds + insects)', 'Up to 15-20 years in captivity', 'The Crested Partridge is a small ground bird with a striking red crest and dark body. It lives in dense forests and is often shy and hard to spot.', 3, '/all_assets/wildlife-28.webp', '/avatars/crested-partridge.png', 32);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (33, 'Scalloped Hammerhead', 'Sphyrna lewini', 6, 'Carnivore', 'Over 30 years in the wild', 'The Scalloped Hammerhead is a shark with a unique hammer-shaped head that helps it detect prey. It often swims in groups and feeds on fish, squid, and crustaceans.', 5, '/all_assets/wildlife-29.webp', '/avatars/scalloped-hammerhead.png', 33);
INSERT OR REPLACE INTO animal (animal_id, common_name, scientific_name, group_id, diet, lifespan, description, conservation_status_id, image_url, avatar_path, image_id) VALUES (34, 'Malayan Birdwing', 'Troides amphrysus', 5, 'Herbivore  (nectar)', 'Unknown', 'The Malayan Birdwing is one of the largest and most beautiful butterflies in the region. Its wings have bold yellow and black patterns, and it is often seen flying in forested areas.', 1, '/all_assets/wildlife-30.webp', '/avatars/malayan-birdwing.png', 34);

