-- Fun Facts
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (7, 1, '🐻', 'The Sun Bear is the SMALLEST bear species in the entire world — much smaller than a polar bear!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQrqY9Wo8MqabRQ4Yt5R9CJnyoApsDytgddHQ&s', 1, 1);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (1, 1, '🐯', 'The Malayan Tiger is found ONLY in Peninsular Malaysia — nowhere else in the world!', 'https://icf.newscdn.net/publisher-c1a3f893382d2b2f8a9aa22a654d9c97/2021/06/5c01d98e074d4f8ac720697bea62756f.jpg=s600', 1, 1);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (13, 1, '🦧', '"Orang Utan" means "Person of the Forest" in the Malay language — a truly amazing name!', 'https://malaysianwildlife.org/wp-content/uploads/2015/08/Orangutan-Pygmy-elephant-conservation-540x600.jpg', 1, 1);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (8, 1, '☀️', 'The pale U-shaped patch on its chest looks like a rising sun — that is exactly how it got its name!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTO4txy_6tJSl1xvzMuKqFdZvqhHK1TuwSqHA&s', 2, 1);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (2, 1, '👑', 'The Malayan Tiger is the national symbol of Malaysia and appears on the national coat of arms!', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Coat_of_arms_of_Malaysia.svg/1920px-Coat_of_arms_of_Malaysia.svg.png', 2, 1);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (14, 1, '🧠', 'Orang Utans share 96.9% of their DNA with humans — making them one of our closest animal relatives!', 'https://www.orangutan.or.id/cfind/source/images/homepage/stories/2025-08-19---how-similar-are-orangutans-to-humans/227.jpg', 2, 1);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (9, 1, '👅', 'The Sun Bear has a tongue up to 25 cm long — it uses it to lick honey and insects out of tree holes!', 'https://www.rekoforest.org/wp-content/uploads/2019/01/RER_Sun-Bear_Helarctos-malayanus._listingfeatured-1.jpg', 3, 2);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (3, 1, '🌙', 'Malayan Tigers are nocturnal hunters — they are most active and hunt mostly at night!', 'https://eitfkkxpd87.exactdn.com/wp-content/uploads/2023/12/How-Tigers-Navigate-Their-World-After-Dark_2175457035.jpg?strip=all', 3, 2);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (15, 1, '💪', 'Orang Utans have arms longer than their entire body — perfect for swinging gracefully between trees!', 'https://www.ecologyasia.com/images-ab/bornean-orang-utan_6862e.jpg', 3, 2);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (10, 1, '🌳', 'Sun Bears are excellent tree climbers and love to sleep and sunbathe high up in the trees!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSJs8fGcvSPtrY7J6WlRuEp-Uy_f89nXBcK3w&s', 4, 2);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (4, 1, '📏', 'Malayan Tigers can grow up to 2.5 metres long — that is as long as a small car!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTUZV4febLp2L4KJjj5Gs6e-sUtqeMDRmxnmw&s', 4, 2);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (16, 1, '🌧️', 'Orang Utans are very clever — they tear off large leaves and hold them over their heads as umbrellas in the rain!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTnpLgXnE6fg9HNTL2uQwlf2kC84ceMU4v09A&s', 4, 2);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (11, 1, '🍯', 'Sun Bears are sometimes called "Honey Bears" because honey is one of their absolute favourite foods!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSauKOmtpF64fw3c7KOY189J1f4DkvyfvoDsA&s', 5, 3);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (5, 1, '🔢', 'Fewer than 150 Malayan Tigers are estimated to be left in the wild today — they are Critically Endangered!', 'https://scontent.fkul15-1.fna.fbcdn.net/v/t39.30808-6/513997529_1141943734642710_5977590577591719504_n.jpg?_nc_cat=103&ccb=1-7&_nc_sid=13d280&_nc_ohc=LLWMdWtSc8gQ7kNvwHlIaNJ&_nc_oc=AdoFDoky0YSDOXtC9522o3M9DYrhLaid-8lD_kEmz8qhNywow9cNTybUr_QhDsu39cCHBysG-GGLbGn2AI0dSnI8&_nc_zt=23&_nc_ht=scontent.fkul15-1.fna&_nc_gid=_Q6EUXBlKj52tOea-uT5qw&_nc_ss=7a389&oh=00_Af2B_lAsABDxW7x9ClmcbmWvMIl7niz0PTQtYxGn7QqgoQ&oe=69DD2A53', 5, 3);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (17, 1, '👶', 'Baby Orang Utans stay with their mothers for up to 12 years — the longest childhood of any wild animal!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRIWBtmty2mvyy-_41lBNoCGFsVSQAofjNtkg&s', 5, 3);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (6, 1, '🧬', 'Every tiger has a completely unique stripe pattern — just like human fingerprints, no two are the same!', 'https://pbs.twimg.com/media/EQbKMqkVAAA4g8X?format=png&name=900x900', 6, 3);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (18, 1, '🌱', 'Orang Utans are the "gardeners of the forest" — they spread seeds everywhere they travel, helping new trees grow!', 'https://d244bobtshbp4.cloudfront.net/_1200xAUTO_crop_center-center_none_ns/Beryl-eating-leaves.jpg', 6, 3);
INSERT OR IGNORE INTO animal_fun_fact (animal_fun_fact_id, animal_id, emoji, fact_text, fact_image_url, fact_order, level_id) VALUES (12, 1, '💪', 'Sun Bears have very strong curved claws that help them tear open tree trunks to find insects and honey!', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRY5xqip469g0wZ0QMYYohOhspWD8Y5QLGU7w&s', 6, 3);

