INSERT OR IGNORE INTO question (question_id, quiz_id, animal_id, question_text, explanation, difficulty) VALUES (1, 1, 1, 'What is the scientific name of the Malayan Tiger?', 'The Malayan Tiger''s subspecies name jacksoni honours tiger conservationist Peter Jackson. Together with Panthera tigris it forms the full scientific name.', 'hard');
